    const std::vector<std::string> loop={"MOV.S R0.x, {0, 0, 0, 0}","REP.S","SEQ.U.CC HC.x, {1, 0, 0, 0}, {0, 0, 0, 0}","BRK (NE.x)","MAD.S R0.y, R0.x, {2, 0, 0, 0}.x, {1, 0, 0, 0}.x","SGE.S R0.y, R0, {1, 0, 0, 0}.x","MOV.U.CC RC.x, -R0.y","IF NE.x","MOV.U.CC RC.x, {1, 0, 0, 0}","BRK (NE.x)","ENDIF","ADD.S R0.x, R0, {1, 0, 0, 0}","ENDREP"};
