    auto declaration=loop;declaration.insert(declaration.begin(),"FLAT ATTRIB fragment_attrib[] = { fragment.attrib[0..31] }");const auto flat=PrepareOriginalParticleInstructions(declaration);require(flat.FlatDeclarations==std::vector<std::size_t>({0})&&flat.OriginalLines.front()==1);
    bool refused=false;try{PrepareOriginalParticleInstructions({"FLAT ATTRIB unknown[] = { fragment.attrib[0..31] }"});}catch(const Refused& e){refused=e.name=="material particle flat declaration";}require(refused);
